package com.andye.warmod.radar.display;
public final class RadarDisplayConstants { public static final int MAX_WIDTH=10, MAX_HEIGHT=10, MAX_PANELS=MAX_WIDTH*MAX_HEIGHT, MAX_OBSERVED_TRACKS=128, BROADCAST_INTERVAL_TICKS=10; public static final double LINK_DISTANCE_BLOCKS=100.0, WORLD_BLOCKS_PER_PANEL=1000.0; private RadarDisplayConstants(){} public static double horizontalRadius(int width){return Math.max(1,Math.min(MAX_WIDTH,width))*WORLD_BLOCKS_PER_PANEL*.5;} public static double verticalRadius(int height){return Math.max(1,Math.min(MAX_HEIGHT,height))*WORLD_BLOCKS_PER_PANEL*.5;} public static double sweepRadius(int width,int height){return Math.min(width,height)*.46;} }